import{GARDEN_CONFIG as u}from"./config.min.js";import{seasonAt as d,wrapHour as f,clamp01 as p}from"./clock.min.js";export const STATES=["sunny","cloudy","windy","stormy"];export function weightsFor(t,n=u){return n.weather.weights[t]||n.weather.weights.summer}export function nextState(t,n,e,o=u){const s=weightsFor(n,o);let r=0;for(const l of STATES)l!==t&&(r+=s[l]||0);if(r<=0)return t;let i=0;const a=p(e)*r;for(const l of STATES)if(l!==t&&(i+=s[l]||0,a<=i))return l;return STATES[STATES.length-1]===t?STATES[0]:STATES[STATES.length-1]}export function dwellFor(t,n=u){const e=n.weather.dwell;return e.min+p(t)*(e.max-e.min)}export function temperatureAt(t,n=u){const e=n.weather.temperature,o=(Math.sin((f(t)-6)*Math.PI/12)+1)/2;return e.coldest+(e.warmest-e.coldest)*o}export function precipFor(t,n,e=u){if(t<=.01)return"none";const o=e.weather.temperature,s=temperatureAt(n,e);return s<o.snowBelow?"snow":s<o.sleetBelow?"sleet":"rain"}export function gustAt(t,n=u){const e=n.weather.gust;let o=0;for(let r=0;r<e.periods.length;r++)o+=e.weights[r]*Math.sin(t*Math.PI*2/e.periods[r]+r*1.7+r*r*.7);const s=Math.pow(p((o+1)/2),e.shape);return e.floor+(e.peak-e.floor)*s}export function blendStates(t,n,e,o=u){const s=o.weather.states[t],r=o.weather.states[n],i=a=>s[a]+(r[a]-s[a])*p(e);return{gloom:i("gloom"),wind:i("wind"),rain:i("rain")}}export function createWeather(t="sunny"){return{state:t,from:t,transition:1,held:0,dwell:30,angle:.8,gloom:0,windStrength:0,gust:1,rain:0,wind:{x:0,z:0},precip:"none"}}export function stepWeather(t,n,e,o=0,s=Math.random,r=!1,i=u){const a=i.weather,l=r?a.reducedTransitionSeconds:a.transitionSeconds;t.transition<1?t.transition=Math.min(1,t.transition+n/l):(t.held+=n,t.held>=t.dwell&&(t.from=t.state,t.state=nextState(t.state,d(e),s(),i),t.dwell=dwellFor(s(),i),t.held=0,t.transition=0));const h=blendStates(t.from,t.state,t.transition,i);t.gloom=h.gloom,t.rain=h.rain;const c=gustAt(o,i);return t.gust=r?1+(c-1)*a.gust.reducedDamp:c,t.windStrength=h.wind*t.gust,t.angle+=a.turnRate*n*(r?.4:1),t.wind.x=Math.cos(t.angle)*t.windStrength,t.wind.z=Math.sin(t.angle)*t.windStrength,t.precip=precipFor(t.rain,e,i),t}export function weatherWords(t){return t.precip==="snow"?"snow":t.precip==="sleet"?"sleet":t.precip==="rain"?"rain":t.state==="windy"||t.transition<.5&&t.from==="windy"?"windy":t.gloom>.35?"cloudy":"clear"}
